import {COPY_SECTIONS} from './review-copy-domain.mjs?v=1';
import {pageReadiness,PAGE_TITLE_MAX,PAGE_DESCRIPTION_MAX} from './review-page-domain.mjs?v=1';

const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export function mountPage({root,controller,materials}){
  let message='',failed=false,errors={};
  const token=path=>'page-'+path.replaceAll('.','-');
  function sourceLabel(item){if(item.error)return'Atualização/conferência necessária';if(!item.revision)return'Não salvo';if(item.dirty)return'Edições não salvas';return item.reviewed?'Revisado':'Salvo; revisão pendente'}
  function field(path,label,value,{area=false,maxLength=2000,placeholder=''}={}){const error=errors[path];return`<label for="${token(path)}">${esc(label)}${area?`<textarea id="${token(path)}" data-page-field="${path}" rows="4" maxlength="${maxLength}" placeholder="${esc(placeholder)}" ${error?'aria-invalid="true"':''}>${esc(value)}</textarea>`:`<input id="${token(path)}" data-page-field="${path}" maxlength="${maxLength}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${error?'aria-invalid="true"':''}>`}${error?`<span class="review-field-error">${esc(error)}</span>`:''}</label>`}
  function refresh(){
    const item=controller.current(),context=controller.sourceContext(),quality=pageReadiness(item.state,context.draft,context);
    root.querySelector('[data-page-status]').textContent=message||(item.error?`Não foi possível ler a página: ${item.error}. O histórico anterior foi preservado.`:JSON.stringify(item.state)!==item.saved?'Alterações ainda não salvas.':'Confira fontes, metadados, imagens e links antes de exportar.');
    root.querySelector('[data-page-status]').classList.toggle('review-error',failed);
    const warning=root.querySelector('[data-page-source-warning]');warning.hidden=quality.snapshotMatches&&item.state.binding===JSON.stringify({id:context.draft.id,product:context.draft.product,market:context.draft.market,language:context.draft.language,publicationUrl:context.draft.publicationUrl,portal:context.draft.portal});
    root.querySelector('[data-page-source-warning-text]').textContent=item.state.sourceSnapshot?'Uma ou mais fontes mudaram desde a conferência. Confirme as versões revisadas para revalidar metadados e textos alternativos.':'Salve e revise as etapas anteriores, depois confirme as fontes desta página.';
    root.querySelector('[data-page-source-status]').textContent=`Materiais: ${sourceLabel(context.materials)} · Análise: ${sourceLabel(context.analysis)} · Reviewer: ${sourceLabel(context.reviewer)} · Oferta: ${sourceLabel(context.offer)} · Imagens: ${sourceLabel(context.images)} · Copy: ${sourceLabel(context.copy)}`;
    root.querySelector('[data-page-quality]').textContent=quality.label;
    const gaps=root.querySelector('[data-page-gaps]');gaps.innerHTML=quality.gaps.length?quality.gaps.map(gap=>`<li>${esc(gap)}</li>`).join(''):'<li>Nenhuma pendência de estrutura identificada. Links e assets são validados por formato; o Hub não faz requisições para confirmar que respondem.</li>';
    root.querySelector('[data-page-reviewed]').checked=item.state.reviewed&&quality.ready;
    root.querySelector('[data-page-save]').disabled=item.error||!context.materials.revision;
    root.querySelector('[data-page-export]').disabled=!quality.exportReady;
    root.querySelector('[data-page-title-count]').textContent=`${item.state.seoTitle.length}/${PAGE_TITLE_MAX}`;
    root.querySelector('[data-page-description-count]').textContent=`${item.state.description.length}/${PAGE_DESCRIPTION_MAX}`;
    for(const def of COPY_SECTIONS){const check=root.querySelector(`[data-page-alt-confirm="${def.key}"]`);if(check)check.checked=item.state.imageAlts[def.key].confirmed}
  }
  function render(){
    const item=controller.current(),context=controller.sourceContext(),copyState=context.copy.state||{},sections=copyState.sections||{},assets=context.assets||{},imageSections=COPY_SECTIONS.filter(def=>sections[def.key]?.status!=='omitted'&&sections[def.key]?.assetKey&&sections[def.key].assetKey!=='none');
    root.innerHTML=`<p>Monte uma prévia responsiva a partir da copy revisada. O HTML final só fica disponível depois de conferir as fontes, os metadados, os textos alternativos e a saída completa.</p>
      <label for="page-review">Review selecionada<select id="page-review" data-page-review>${materials.list().map(row=>`<option value="${esc(row.draft.id)}" ${row.draft.id===context.draft.id?'selected':''}>${esc(row.draft.product||'Nova review (salve no passo 1)')} · ${esc(row.draft.market||'mercado a definir')} · ${esc(row.draft.id.slice(0,8))}</option>`).join('')}</select></label>
      <p data-page-status role="status" aria-live="polite"></p>${item.error?`<p class="review-error" role="alert">Não foi possível ler a página: ${esc(item.error)}. O histórico anterior foi preservado.</p>`:''}
      <div class="review-analysis-warning" data-page-source-warning><p data-page-source-warning-text></p><button class="btn hub-standard-action" type="button" data-page-action="sources">Confirmar fontes revisadas</button></div>
      <p class="review-page-source-status" data-page-source-status></p>
      <section><h4>SEO e identidade editorial</h4><p>O canonical vem da URL prevista de publicação do passo 1 e é incluído apenas se for HTTPS público. O título e a descrição abaixo aparecem na página e nos metadados.</p><div class="review-form-grid">${field('seoTitle','Título SEO e H1',item.state.seoTitle,{maxLength:PAGE_TITLE_MAX,placeholder:`Até ${PAGE_TITLE_MAX} caracteres`})}<span class="review-page-counter" data-page-title-count></span></div><div class="review-form-grid">${field('description','Descrição SEO e introdução visível',item.state.description,{area:true,maxLength:PAGE_DESCRIPTION_MAX,placeholder:`Até ${PAGE_DESCRIPTION_MAX} caracteres`})}<span class="review-page-counter" data-page-description-count></span></div><dl class="review-page-identity"><dt>Canonical</dt><dd><code>${esc(context.draft.publicationUrl||'Pendente — informe no passo 1')}</code></dd><dt>Portal / publisher</dt><dd>${esc(context.draft.portal||'Pendente — informe no passo 1')}</dd><dt>Idioma</dt><dd>${esc(context.draft.language||'Pendente — informe no passo 1')}</dd></dl></section>
      <section><h4>Texto alternativo das imagens</h4><p>Descreva o que aparece na imagem. Não acrescente benefício ou resultado que ela não demonstre. Cada texto exige confirmação manual; URLs de imagem não são carregadas até solicitar a prévia.</p>${imageSections.length?imageSections.map(def=>{const alt=item.state.imageAlts[def.key],url=assets[sections[def.key].assetKey];return`<div class="review-page-alt"><strong>${def.number}. ${esc(def.title)}</strong><small>${esc(sections[def.key].assetKey)} · ${url?'URL atual disponível':'URL ainda pendente'}</small>${field(`imageAlts.${def.key}.text`,'Alt text',alt.text,{maxLength:1000,placeholder:'Descreva a imagem para leitores de tela.'})}<label class="review-analysis-check"><input type="checkbox" data-page-alt-confirm="${def.key}" data-page-field="imageAlts.${def.key}.confirmed" ${alt.confirmed?'checked':''}>Conferi que o texto alternativo descreve a imagem.</label></div>`}).join(''):'<p>Nenhuma imagem está vinculada às seções atuais da copy.</p>'}</section>
      <section><h4>Validação, revisão e entrega</h4><p data-page-quality class="review-analysis-warning"></p><details><summary>Ver todas as pendências</summary><ul data-page-gaps></ul></details><label class="review-analysis-check"><input type="checkbox" data-page-reviewed>Revisei a prévia completa, a identidade, os links e os dados estruturados.</label><div class="review-actions"><button class="btn hub-standard-action" type="button" data-page-action="preview">Atualizar prévia</button><button class="btn primary hub-standard-action" type="button" data-page-action="save" data-page-save ${item.error||!context.materials.revision?'disabled':''}>Salvar etapa</button><button class="btn hub-standard-action" type="button" data-page-action="export" data-page-export disabled>Baixar HTML final</button></div><p>JSON-LD usa WebPage e Organization, refletindo o conteúdo visível; não inclui Review/AggregateRating. Canonical e dados estruturados descrevem a página, mas não garantem rastreamento, indexação ou posição. O Hub não gera sitemap. A saída é um HTML único com CSS embutido e URLs remotas de imagem; links e imagens não são verificados por requisição. Sem upload ou publicação automática.</p><iframe title="Prévia responsiva da página de review" sandbox="" referrerpolicy="no-referrer" loading="lazy" data-page-preview hidden></iframe></section>`;
    refresh();
  }
  function update(event){const path=event.target.dataset.pageField;if(!path)return;controller.update(path,event.target.type==='checkbox'?event.target.checked:event.target.value);message='';failed=false;if(errors[path])delete errors[path];root.querySelector('[data-page-preview]').hidden=true;refresh()}
  root.addEventListener('input',event=>{if(event.target.type!=='checkbox'&&event.target.tagName!=='SELECT')update(event)});
  root.addEventListener('change',event=>{try{if(event.target.matches('[data-page-review]')){materials.select(event.target.value);message='';errors={};failed=false;render()}else if(event.target.matches('[data-page-reviewed]')){controller.setReviewed(event.target.checked);message='';failed=false;refresh()}else if(event.target.type==='checkbox')update(event)}catch(error){errors=error.fields||{};message=`Não foi possível concluir: ${error.message}`;failed=true;refresh();root.querySelector('[aria-invalid="true"]')?.focus()}});
  root.addEventListener('click',async event=>{const button=event.target.closest('[data-page-action]'),action=button?.dataset.pageAction;if(!action)return;try{
    if(action==='sources'){controller.confirmSources();message='Fontes atuais vinculadas; confira metadados e alt texts novamente.';failed=false;errors={};render()}
    if(action==='preview'){root.querySelector('[data-page-preview]').srcdoc=controller.previewHtml();root.querySelector('[data-page-preview]').hidden=false;root.querySelector('[data-page-status]').textContent='Prévia interna atualizada; ainda não é o arquivo aprovado para publicação.'}
    if(action==='save'){button.disabled=true;const id=materials.current().draft.id;try{if(navigator.locks?.request)await navigator.locks.request('hub-review-page-'+id,()=>controller.save(id));else controller.save(id);message='Etapa de página salva neste navegador; versões anteriores foram preservadas.';failed=false;errors={};render()}finally{button.disabled=false}}
    if(action==='export'){const html=controller.exportHtml(),url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),link=document.createElement('a'),product=materials.current().draft.product.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)||'review';link.href=url;link.download=`${product}-review.html`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('HTML final exportado. Hospede manualmente e confira canonical, links e imagens no domínio publicado.');failed=false}
  }catch(error){message=`Não foi possível concluir: ${error.message}`;failed=true;errors=error.fields||{};refresh()}});
  render();
}
